INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q152218', 'Nine Years'' War', 'The Nine Years'' War was a European great power conflict from 1688 to 1697 between France and the Grand Alliance. Fought primarily in Europe, related conflicts include the Williamite war in Ireland, and King William''s War in North America.', 1688, 9, 27, 1697, 9, NULL, 'day', '27 September 1688 – September 1697', 76, 'https://en.wikipedia.org/wiki/Nine_Years''_War'),
  ('Q150701', 'War of the Spanish Succession', 'The War of the Spanish Succession (1701 to 1714) was a European great power conflict. The death of Charles II of Spain in November 1700 without children led to a succession crisis between Philip of Anjou and Archduke Charles of Austria.', 1701, 3, NULL, 1714, 9, 7, 'month', 'March 1701 – 7 September 1714', 82, 'https://en.wikipedia.org/wiki/War_of_the_Spanish_Succession'),
  ('Q154697', 'French and Indian War', 'The French and Indian War (1754–1763) was a conflict in North America between Great Britain and France, along with their respective Indigenous allies. Historians generally consider it part of the global Seven Years'' War, which lasted from 1756 to 1763, although in the United States it is often viewed as a distinct conflict unassociated with any larger European war.', 1754, 5, 28, 1763, 10, 7, 'day', '28 May 1754 – 7 October 1763', 76, 'https://en.wikipedia.org/wiki/French_and_Indian_War'),
  ('Q192769', 'American Revolution', 'The American Revolution (1765–1789) was a political movement in the Thirteen Colonies of Great Britain. It began as a colonial rebellion and evolved into a revolution, the result of which was the creation of the United States following the colonies'' victory in the American Revolutionary War (1775–1783) and British recognition of their sovereign independence in the Treaty of Paris.', 1763, 3, 22, 1783, NULL, NULL, 'day', '22 March 1763 – 1783', 86, 'https://en.wikipedia.org/wiki/American_Revolution'),
  ('Q19024', 'Boston Tea Party', 'The Boston Tea Party was an act of protest that took place on December 16, 1773, during the American Revolution. Initiated by the Sons of Liberty in Boston, the capital of Massachusetts, one of the Thirteen Colonies of British America, it escalated tensions between Great Britain and the Patriots, who opposed British policy towards its American colonies.', 1773, 12, 16, NULL, NULL, NULL, 'day', '16 December 1773', 81, 'https://en.wikipedia.org/wiki/Boston_Tea_Party'),
  ('Q127912', 'United States Declaration of Independence', 'The Declaration of Independence, headed The unanimous Declaration of the thirteen united States of America on the document directed to be engrossed by Congress on July 19, 1776, is the founding document of the United States. On July 4, 1776, it was adopted unanimously by the Second Continental Congress, who were convened at the Pennsylvania State House, later renamed Independence Hall, in Philadelphia.', 1776, 7, 4, NULL, NULL, NULL, 'day', '4 July 1776', 91, 'https://en.wikipedia.org/wiki/United_States_Declaration_of_Independence'),
  ('Q7512984', 'signing of the United States Declaration of Independence', 'The signing of the United States Declaration of Independence occurred primarily on August 2, 1776, at the Pennsylvania State House, later renamed Independence Hall, in Philadelphia. The 56 delegates to the Second Continental Congress represented the Thirteen Colonies, of which 12 voted to approve the Declaration of Independence on July 4, 1776.', 1776, 8, 2, NULL, NULL, NULL, 'day', '2 August 1776', 37, 'https://en.wikipedia.org/wiki/Signing_of_the_United_States_Declaration_of_Independence'),
  ('Q193155', 'Louisiana Purchase', 'The Louisiana Purchase (French: Vente de la Louisiane, lit. ''Sale of Louisiana'') was the acquisition of the territory of Louisiana by the United States from the French First Republic in 1803. This consisted of most of the land in the Mississippi River''s drainage basin west of the river.', 1803, 4, 30, NULL, NULL, NULL, 'day', '30 April 1803', 78, 'https://en.wikipedia.org/wiki/Louisiana_Purchase'),
  ('Q26013', 'War of 1812', 'The War of 1812 was a conflict initiated by the United States against the United Kingdom and its allies fought mainly in North America and at sea during the wider Napoleonic Wars. The United States declared war on Britain on 18 June 1812.', 1812, 6, 18, 1815, 2, 18, 'day', '18 June 1812 – 18 February 1815', 85, 'https://en.wikipedia.org/wiki/War_of_1812'),
  ('Q727854', 'Missouri Compromise', 'The Missouri Compromise (also known as the Compromise of 1820) was federal legislation of the United States that balanced the desires of some northern states to prevent the expansion of slavery in the country with those of southern states to expand it. It admitted Missouri as a slave state and Maine as a free state and declared a policy of prohibiting slavery in the remaining Louisiana Purchase lands north of the 36°30′ parallel.', 1820, NULL, NULL, NULL, NULL, NULL, 'year', '1820', 67, 'https://en.wikipedia.org/wiki/Missouri_Compromise'),
  ('Q235344', 'Battle of the Alamo', 'The Battle of the Alamo (February 23 – March 6, 1836) was a pivotal event and military engagement in the Texas Revolution. Following a 13-day siege, Mexican troops under president and general Antonio López de Santa Anna reclaimed the Alamo Mission near San Antonio de Béxar (now San Antonio).', 1836, 2, 23, 1836, 3, 6, 'day', '23 February 1836 – 6 March 1836', 75, 'https://en.wikipedia.org/wiki/Battle_of_the_Alamo'),
  ('Q2572004', '1838 Mormon War', 'The 1838 Mormon War (or Missouri Mormon War) was a period of civil unrest in northern Missouri during the summer and fall of 1838 that concluded with the state-mandated expulsion of Mormons (Latter Day Saints) from the state. Tensions originated in 1831 when Mormons designated Jackson County, Missouri as a gathering place.', 1838, 11, 1, NULL, NULL, NULL, 'day', '1 November 1838', 47, 'https://en.wikipedia.org/wiki/1838_Mormon_War'),
  ('Q6683', 'Mexican-American War', 'The Mexican–American War, also known in the United States as the Mexican War and in Mexico as the United States intervention in Mexico, (April 25, 1846 – February 2, 1848) was an invasion of Mexico by the United States. It followed the 1845 American annexation of Texas, which Mexico still considered its territory because it refused to recognize the Treaties of Velasco, signed by President Antonio López de Santa Anna after he was captured by the Texian Army during the 1836 Texas Revolution.', 1840, NULL, NULL, 1848, 2, 2, 'decade', '1840s – 2 February 1848', 82, 'https://en.wikipedia.org/wiki/Mexican%E2%80%93American_War'),
  ('Q4302809', 'Battle of Nauvoo', 'The history of Nauvoo, Illinois, starts with the Sauk and Meskwaki tribes who frequented the area, on a bend of the Mississippi River in Hancock County, some 53 miles (85 km) north of today''s Quincy. They called the area "Quashquema", in honor of the Native American chief who headed a Sauk and Fox settlement numbering nearly 500 lodges.', 1846, 9, 16, NULL, NULL, NULL, 'day', '16 September 1846', 21, 'https://en.wikipedia.org/wiki/History_of_Nauvoo%2C_Illinois'),
  ('Q331377', 'Bleeding Kansas', 'Bleeding Kansas, Bloody Kansas, or the Border War, was a series of violent civil confrontations in the Kansas Territory, and to a lesser extent in western Missouri, between 1854 and 1859. It emerged from a political and ideological debate over whether slavery should be permitted in the proposed state of Kansas.', 1854, NULL, NULL, 1861, NULL, NULL, 'year', '1854–1861', 63, 'https://en.wikipedia.org/wiki/Bleeding_Kansas'),
  ('Q1501025', 'Utah War', 'The Utah War (1857–1858), also known as the Utah Expedition, the Utah Campaign, Buchanan''s Blunder, the Mormon War, or the Mormon Rebellion, was an armed confrontation between the armed forces of the US government and the Mormon settlers in the Utah Territory. The confrontation lasted from May 1857 to July 1858.', 1857, 3, NULL, 1858, 7, NULL, 'month', 'March 1857 – July 1858', 60, 'https://en.wikipedia.org/wiki/Utah_War'),
  ('Q33132', 'Battle of Gettysburg', 'The Battle of Gettysburg (locally ) (July 1–3, 1863) was fought in the American Civil War between the Union and Confederate armies in and around Gettysburg, Pennsylvania. The battle is widely considered the turning point of the war, leading to the preservation of the Union and freedom from slavery.', 1863, 7, 1, 1863, 7, 3, 'day', '1 July 1863 – 3 July 1863', 77, 'https://en.wikipedia.org/wiki/Battle_of_Gettysburg'),
  ('Q8676', 'American Civil War', 'The American Civil War (April 12, 1861 – May 26, 1865; also known by other names) was a civil war in the United States between the Union ("the North") and the Confederacy ("the South"), which was formed in 1861 by Southern states that had seceded from the Union to preserve the institution of slavery. The South saw slavery as threatened because of the election of Abraham Lincoln as president in 1860, the abolitionist movement, and the growing electoral power of the North.', 1865, 4, 12, 1865, 4, 9, 'day', '12 April 1865 – 9 April 1865', 97, 'https://en.wikipedia.org/wiki/American_Civil_War'),
  ('Q1025404', 'assassination of Abraham Lincoln', 'On April 14, 1865, Abraham Lincoln, the 16th president of the United States, was shot in the head while attending a play at Ford''s Theatre in Washington, D.C.. He died the following day, six weeks into his second term and a month before the conclusion of the American Civil War.', 1865, 4, 15, NULL, NULL, NULL, 'day', '15 April 1865', 72, 'https://en.wikipedia.org/wiki/Assassination_of_Abraham_Lincoln'),
  ('Q309029', 'Alaska Purchase', 'The Alaska Purchase in 1867 resulted in the transfer of Russian America to the United States for $7.2 million (equivalent to $136 million in 2025). On April 9 of that year, the United States Senate ratified a bilateral treaty that had been signed on March 30, and American sovereignty became legally effective across the territory on October 18.', 1867, 3, 30, NULL, NULL, NULL, 'day', '30 March 1867', 77, 'https://en.wikipedia.org/wiki/Alaska_Purchase'),
  ('Q631489', 'Klondike Gold Rush', 'The Klondike Gold Rush was a migration by an estimated 100,000 prospectors to the Klondike region of Yukon in northwestern Canada, between 1896 and 1898. Gold was discovered there by local miners on August 16, 1896; when the news reached Seattle and San Francisco the following year, it triggered a stampede of prospectors.', 1896, NULL, NULL, 1899, NULL, NULL, 'year', '1896–1899', 72, 'https://en.wikipedia.org/wiki/Klondike_Gold_Rush'),
  ('Q12583', 'Spanish–American War', 'The Spanish–American War (April 21 – August 13, 1898) was an armed conflict fought between the United States and Spain in 1898. It began with the sinking of the USS Maine in Havana Harbor in Cuba, and eventually resulted in the U.S. acquiring Puerto Rico, Guam, the Philippines, and establishing a protectorate over Cuba.', 1898, NULL, NULL, 1898, 8, 11, 'year', '1898', 85, 'https://en.wikipedia.org/wiki/Spanish%E2%80%93American_War'),
  ('Q548067', 'Treaty of Portsmouth', 'The Treaty of Portsmouth formally ended the 1904–1905 Russo-Japanese War. It was signed on September 5, 1905, after negotiations from August 6 to 30, at the Portsmouth Naval Shipyard in Kittery, Maine (then part of Portsmouth, New Hampshire), United States.', 1905, 9, 5, NULL, NULL, NULL, 'day', '5 September 1905', 75, 'https://en.wikipedia.org/wiki/Treaty_of_Portsmouth'),
  ('Q211386', '1906 San Francisco earthquake', 'A magnitude 7.9 earthquake struck the coast of Northern California at 05:12 am Pacific Standard Time on Wednesday, April 18, 1906. With a maximum Mercalli intensity of XI (Extreme), it created high-intensity shaking from Eureka on the North Coast to the Salinas Valley, an agricultural region to the south of the San Francisco Bay Area.', 1906, 4, 18, NULL, NULL, NULL, 'day', '18 April 1906', 75, 'https://en.wikipedia.org/wiki/1906_San_Francisco_earthquake'),
  ('Q361', 'World War I', 'World War I, or the First World War (28 July 1914 – 11 November 1918), also known as the Great War, was a global conflict between two coalitions: the Allies (or Entente) and the Central Powers. One of the deadliest conflicts in history, World War I caused 15 to 22 million deaths, including those resulting from war crimes and genocides.', 1918, 11, 11, 1918, 11, 11, 'day', '11 November 1918', 100, 'https://en.wikipedia.org/wiki/World_War_I'),
  ('Q8698', 'Great Depression', 'The Great Depression was a severe global economic downturn from 1929 to 1939. The period was marked by high rates of unemployment and poverty, drastic reductions in industrial production and international trade, and widespread bank and business failures around the world.', 1929, 10, 29, 1941, NULL, NULL, 'day', '29 October 1929 – 1941', 93, 'https://en.wikipedia.org/wiki/Great_Depression'),
  ('Q696482', 'Great Depression in the United States', 'In the United States, the Great Depression is commonly (though not universally) dated to the Wall Street crash of October 1929. The nadir came in 1931–1933, and recovery came in 1940.', 1929, 10, 24, 1939, NULL, NULL, 'day', '24 October 1929 – 1939', 47, 'https://en.wikipedia.org/wiki/Great_Depression_in_the_United_States'),
  ('Q362', 'World War II', 'World War II, or the Second World War (1 September 1939 – 2 September 1945), was a global conflict between two coalitions: the Allies and the Axis powers. Nearly all of the world''s countries were involved, with many engaging in total war on an unprecedented scale.', 1939, 9, 1, 1945, 9, 2, 'day', '1 September 1939 – 2 September 1945', 100, 'https://en.wikipedia.org/wiki/World_War_II'),
  ('Q52418', 'Attack on Pearl Harbor', 'The Empire of Japan launched a surprise military attack on the US Pacific Fleet at its naval base at Pearl Harbor in Oahu, Hawaii, on December 7, 1941. At the time, the US was a neutral country in World War II. The air raid on Pearl Harbor, which was launched from aircraft carriers, prompted the US to declare war on Japan the next day.', 1941, 12, 7, NULL, NULL, NULL, 'day', '7 December 1941', 85, 'https://en.wikipedia.org/wiki/Attack_on_Pearl_Harbor'),
  ('Q173034', 'Battle of Midway', 'The Battle of Midway was a major naval battle in the Pacific Theater of World War II that took place on 4–7 June 1942, six months after Japan''s attack on Pearl Harbor and one month after the Battle of the Coral Sea. The Japanese Combined Fleet under the command of Isoroku Yamamoto suffered a decisive defeat by two carrier strike groups of the U.S. Pacific Fleet near Midway Atoll, about 1,300 mi (1,100 nmi; 2,100 km) northwest of Oahu.', 1942, 6, 4, 1942, 6, 7, 'day', '4 June 1942 – 7 June 1942', 80, 'https://en.wikipedia.org/wiki/Battle_of_Midway'),
  ('Q488', 'atomic bombings of Hiroshima and Nagasaki', 'On 6 and 9 August 1945, the United States detonated two atomic bombs over the Japanese cities of Hiroshima and Nagasaki, respectively, during the final days of World War II. The aerial bombings killed 150,000 to 246,000 people, most of whom were civilians, and remain the first and only uses of nuclear weapons in an armed conflict. In the final year of World War II, the Allies prepared for a costly invasion of the Japanese mainland.', 1945, 8, 6, NULL, NULL, NULL, 'day', '6 August 1945', 87, 'https://en.wikipedia.org/wiki/Atomic_bombings_of_Hiroshima_and_Nagasaki'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q295875', 'ANZUS', 'The Australia, New Zealand, United States Security Treaty (ANZUS or ANZUS Treaty) is a collective security agreement between Australia, New Zealand, and the United States that was signed in 1951, and from which New Zealand has been partially suspended since 1986. It firstly recommits the parties to the purposes of the United Nations, prohibiting the use of force or threats except in self-defence.', 1951, 9, 1, NULL, NULL, NULL, 'day', '1 September 1951', 75, 'https://en.wikipedia.org/wiki/ANZUS'),
  ('Q392541', 'Treaty of San Francisco', 'The Treaty of San Francisco, also called the Treaty of Peace with Japan, re-established peaceful relations between Japan and the Allies on behalf of the United Nations by ending the legal state of war, military occupation and providing for redress for hostile actions up to and including World War II. It was signed by 49 nations on September 8, 1951, in San Francisco, United States, at the War Memorial Opera House. Italy and China were not invited, the latter due to disagreements on whether the Republic of China or the People''s Republic of China represented the Chinese people.', 1951, 9, 8, NULL, NULL, NULL, 'day', '8 September 1951', 76, 'https://en.wikipedia.org/wiki/Treaty_of_San_Francisco'),
  ('Q128160', 'Cuban Missile Crisis', 'The Cuban Missile Crisis, also known as the October Crisis in Cuba (Spanish: Crisis de Octubre), or the Caribbean Crisis (Russian: Карибский кризис, romanized: Karibskiy krizis), was a 13-day confrontation between the governments of the United States and the Soviet Union, when American deployments of nuclear missiles in the United Kingdom, Italy and Turkey were matched by Soviet deployments of nuclear missiles in Cuba. The crisis lasted from 16 to 28 October 1962.', 1962, NULL, NULL, 1962, 10, 28, 'year', '1962', 86, 'https://en.wikipedia.org/wiki/Cuban_Missile_Crisis'),
  ('Q193484', 'assassination of John F. Kennedy', 'On Friday, November 22, 1963, John F. Kennedy, the 35th president of the United States, was assassinated while riding in a presidential motorcade through Dallas, Texas. Kennedy was in the vehicle with First Lady Jacqueline Kennedy, Texas governor John Connally, and Connally''s wife Nellie, when he was fatally shot from the nearby Texas School Book Depository by Lee Harvey Oswald, a former U.S. Marine.', 1963, 11, 22, NULL, NULL, NULL, 'day', '22 November 1963', 78, 'https://en.wikipedia.org/wiki/Assassination_of_John_F._Kennedy'),
  ('Q194082', 'Apollo 1', 'Apollo 1, initially designated AS-204, was planned to be the first crewed mission of the Apollo program, the American undertaking to land the first man on the Moon. It was planned to be launched on February 21, 1967, as the first low Earth orbital test of the Apollo command and service module.', 1967, 1, 27, NULL, NULL, NULL, 'day', '27 January 1967', 77, 'https://en.wikipedia.org/wiki/Apollo_1'),
  ('Q42761', 'Watergate scandal', 'The Watergate scandal, also simply called Watergate, was a political scandal in the United States involving the administration of President Richard Nixon. On June 17, 1972, operatives associated with Nixon''s 1972 re-election campaign were caught burglarizing and planting listening devices in the Democratic National Committee headquarters at Washington, D.C.''s Watergate complex.', 1972, 6, 17, 1974, 8, 9, 'day', '17 June 1972 – 9 August 1974', 84, 'https://en.wikipedia.org/wiki/Watergate_scandal'),
  ('Q8740', 'Vietnam War', 'The Vietnam War (c. 1955 – 30 April 1975) was an armed conflict in Vietnam, Laos, and Cambodia fought between North Vietnam (Democratic Republic of Vietnam) and South Vietnam (Republic of Vietnam) and their allies. North Vietnam was supported by the Soviet Union and China, while South Vietnam was supported by the United States and other anti-communist nations.', 1975, 4, 30, 1975, 4, 30, 'day', '30 April 1975', 97, 'https://en.wikipedia.org/wiki/Vietnam_War'),
  ('Q868261', 'Black Monday', 'Black Monday (also known as Black Tuesday in some parts of the world due to time zone differences) was a global, severe and largely unexpected stock market crash on Monday, October 19, 1987. Worldwide losses were estimated at US$1.71 trillion.', 1987, 10, 19, NULL, NULL, NULL, 'day', '19 October 1987', 69, 'https://en.wikipedia.org/wiki/Black_Monday_(1987)'),
  ('Q37643', 'Gulf War', 'The Gulf War was an armed conflict between Iraq and a 42-country coalition led by the United States in response to the Iraqi invasion of Kuwait on 2 August 1990. The coalition''s efforts were carried out in two phases: Operation Desert Shield, which marked the military buildup in the Persian Gulf region from August 1990 to January 1991; and Operation Desert Storm, which began with the bombing campaign against Iraq on 17 January and continued until the liberation of Kuwait on 28 February.', 1990, 8, 2, 1991, 2, 28, 'day', '2 August 1990 – 28 February 1991', 90, 'https://en.wikipedia.org/wiki/Gulf_War'),
  ('Q696187', '1992 Los Angeles riots', 'Los Angeles, California, experienced a series of riots and civil disturbances from April 29 to May 3, 1992. Civil unrest began in South Central Los Angeles on April 29, after a jury acquitted four officers of the Los Angeles Police Department (LAPD) charged with using excessive force in the arrest and beating of Rodney King.', 1992, NULL, NULL, 1992, 5, 4, 'year', '1992', 69, 'https://en.wikipedia.org/wiki/1992_Los_Angeles_riots'),
  ('Q1778229', 'United Nations Operation in Somalia II', 'The United Nations Operation in Somalia II (UNOSOM II) was the second phase of the United Nations intervention in Somalia and took place from March 1993 until March 1995, following the outbreak of the Somali Civil War in 1991. UNOSOM II carried on from the transitory United States-controlled (UN-sanctioned) Unified Task Force (UNITAF), which had been preceded by UNOSOM I. Notably, UNOSOM II embarked on a nation-building mission, diverging from its predecessors.', 1993, 3, NULL, 1995, 3, 28, 'month', 'March 1993 – 28 March 1995', 56, 'https://en.wikipedia.org/wiki/United_Nations_Operation_in_Somalia_II'),
  ('Q155723', 'NATO bombing of Yugoslavia', 'The North Atlantic Treaty Organization (NATO) carried out an aerial bombing campaign against the Federal Republic of Yugoslavia (contemporary name of Serbia and Montenegro) during the Kosovo War. The air strikes lasted from 24 March 1999 to 10 June 1999.', 1999, 3, 24, 1999, 6, 10, 'day', '24 March 1999 – 10 June 1999', 77, 'https://en.wikipedia.org/wiki/NATO_bombing_of_Yugoslavia'),
  ('Q154510', 'Great Recession', 'The Great Recession was a period of contraction in economies around the world (particularly in the western world and associated countries) that occurred from late 2007 to mid-2009, overlapping with the closely related 2008 financial crisis. The scale and timing of the recession varied from country to country (see map).', 2000, NULL, NULL, NULL, NULL, NULL, 'decade', '2000s', 77, 'https://en.wikipedia.org/wiki/Great_Recession'),
  ('Q10806', 'September 11 attacks', 'The September 11 attacks, colloquially known as 9/11, were a coordinated series of suicide attacks perpetrated by the Islamic terrorist organization al-Qaeda against the United States in 2001. A total of 19 hijackers commandeered four commercial passenger airliners.', 2001, 9, 11, NULL, NULL, NULL, 'day', '11 September 2001', 97, 'https://en.wikipedia.org/wiki/September_11_attacks'),
  ('Q182865', 'War in Afghanistan (2001–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2001, 10, 7, 2021, 8, 30, 'day', '7 October 2001 – 30 August 2021', 84, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2001%E2%80%932021)'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q16422', 'Hurricane Katrina', 'Hurricane Katrina was an extremely powerful and catastrophic tropical cyclone that affected the Southeastern United States in late August 2005, particularly in and around the city of New Orleans. Katrina became the costliest tropical cyclone in the United States, with damage estimated at $125 billion ($206 billion when adjusted for inflation).', 2005, NULL, NULL, 2005, 8, 31, 'year', '2005', 82, 'https://en.wikipedia.org/wiki/Hurricane_Katrina'),
  ('Q844541', 'United States subprime mortgage crisis', 'The American subprime mortgage crisis was a multinational financial crisis that occurred between 2007 and 2010, contributing to the 2008 financial crisis. It led to a severe economic recession, with millions becoming unemployed and many businesses going bankrupt.', 2007, NULL, NULL, NULL, NULL, NULL, 'year', '2007', 66, 'https://en.wikipedia.org/wiki/Subprime_mortgage_crisis'),
  ('Q896666', '2007–2008 financial crisis', 'The 2008 financial crisis was a major worldwide financial crisis which started in the United States. The first phase was the subprime mortgage crisis, which began in early 2007 as mortgage-backed securities (MBS) tied to U.S. real estate, and a vast web of derivatives linked to those MBS, collapsed in value.', 2007, NULL, NULL, NULL, NULL, NULL, 'year', '2007', 83, 'https://en.wikipedia.org/wiki/2008_financial_crisis'),
  ('Q180654', 'Occupy Wall Street', 'Occupy Wall Street (O.W.S.) was a left-wing populist and progressive movement against economic inequality, capitalism, corporate greed, big finance, and the influence of money in politics. It began in Zuccotti Park, located in New York City''s Financial District, and lasted for fifty-nine days—from September 17 to November 15, 2011.', 2011, 9, 17, NULL, NULL, NULL, 'day', '17 September 2011', 75, 'https://en.wikipedia.org/wiki/Occupy_Wall_Street'),
  ('Q210714', '2011 military intervention in Libya', 'On 19 March 2011, a NATO-led coalition began a military intervention into the ongoing Libyan Civil War to implement United Nations Security Council Resolution 1973 (UNSCR 1973). The UN Security Council passed the resolution with ten votes in favour and five abstentions, with the stated intent to have "an immediate ceasefire in Libya, including an end to the current attacks against civilians, which it said might constitute ''crimes against humanity'' ...', 2011, 10, 31, 2011, 10, 31, 'day', '31 October 2011', 72, 'https://en.wikipedia.org/wiki/2011_military_intervention_in_Libya'),
  ('Q11086137', 'Boston Marathon bombings', 'The Boston Marathon bombing, sometimes referred to as simply the Boston bombing, was an Islamist domestic terrorist attack that took place during the 117th annual Boston Marathon on April 15, 2013. Four hours into the race, Tamerlan Tsarnaev and Dzhokhar Tsarnaev detonated two homemade pressure cooker bombs containing explosives and steel shrapnel.', 2013, 4, 15, NULL, NULL, NULL, 'day', '15 April 2013', 78, 'https://en.wikipedia.org/wiki/Boston_Marathon_bombing'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q18121212', 'United States intervention in Syria', 'The United States officially intervened in the Syrian civil war on 22 September 2014 with the stated aim of combatting the Islamic State (ISIL/ISIS) militant organization. The intervention was part of Operation Inherent Resolve and saw the US support both anti-ISIL and anti-Assad factions, including the Syrian Armed Forces under the transitional government and the YPG-led Syrian Democratic Forces (SDF).', 2014, 9, 22, NULL, NULL, NULL, 'day', '22 September 2014', 55, 'https://en.wikipedia.org/wiki/United_States_intervention_in_Syria'),
  ('Q24561572', 'Orlando nightclub shooting', 'On June 12, 2016, 29-year-old Omar Mateen shot and killed 49 people and wounded 58 in a mass shooting at Pulse, a gay nightclub in Orlando, Florida, United States. Pulse was hosting a "Latin Night", and most of the victims were of Latino descent.', 2016, 6, 12, NULL, NULL, NULL, 'day', '12 June 2016', 77, 'https://en.wikipedia.org/wiki/Pulse_nightclub_shooting'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q83873577', 'COVID-19 pandemic in the United States', 'On 31 December 2019, China announced the discovery of a cluster of pneumonia cases in Wuhan. The first American case of COVID-19 was reported on January 20, and Health and Human Services Secretary Alex Azar declared a public health emergency on January 31.', 2020, 1, 21, NULL, NULL, NULL, 'day', '21 January 2020', 76, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_the_United_States'),
  ('Q104705419', 'January 6 United States Capitol attack', 'On January 6, 2021, the United States Capitol in Washington, D.C., was attacked by a mob of supporters of President Donald Trump. Academic debate exists about whether to characterize the event as an attempted coup, an attempted self-coup, or neither.', 2021, 1, 6, NULL, NULL, NULL, 'day', '6 January 2021', 82, 'https://en.wikipedia.org/wiki/January_6_United_States_Capitol_attack');
